@startuml
class Customer {
  +name : string
  +surname : string
  +age : int
  +address : string
  +profession : string
}

class Subscription {
  +type : string
}

class Service {
  +name : string
}

class WorkoutPlan {
  +exercises : string[]
  +repetitions : int
  +frequency : int
}

class MedicalStaff {
}

class MedicalCheck {
  +weight : float
  +body_fat : float
  +electrocardiogram : string
  +resting_heartbeat : int
  +stress_heartbeat : int
}

Customer "1" -- "1" Subscription : has
Customer "1" -- "*" Service : requests
Customer "1" -- "0..1" WorkoutPlan : is associated with
Customer "0..1" -- "0..*" MedicalCheck : undergoes
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Customer : assists
@enduml

